    const PAYLOAD_SCHEMA: Option<&'static str> = Some(
        "{\"$defs\":{\"Ext\":{\"additionalProperties\":true,\"description\":\"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.\",\"minProperties\":1,\"propertyNames\":{\"pattern\":\"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+$\"},\"title\":\"Ext\",\"type\":\"object\"},\"MemoryKey\":{\"description\":\"Agent-chosen identifier for an item within a context. Opaque to the maintainer: it MUST NOT be parsed, normalized, or case-folded, and prefix matching in `vta/memory/list` is a byte-prefix comparison over the UTF-8 encoding. Agents SHOULD use `/`-delimited hierarchical keys (`contact/billing`, `preference/timezone`) so that `prefix` can address a family of items, but the delimiter is a convention between an agent and itself. A key is content as well as an address: a key naming a person, a condition or a dispute discloses something to anyone who can list the context, even without its value.\",\"maxLength\":512,\"minLength\":1,\"pattern\":\"^[^\\\\u0000]+$\",\"title\":\"MemoryKey\",\"type\":\"string\"},\"MemoryRecord\":{\"additionalProperties\":false,\"description\":\"A memory item as the maintainer holds it. `value` is absent in two distinct situations and a consumer MUST NOT conflate them: the item is a tombstone (`deleted` is true), or the caller asked for a metadata-only view (`vta/memory/list` without `includeValues`). This is why `deleted` is required rather than defaulted — a consumer that infers deletion from an absent value gets the tombstone case wrong exactly when convergence depends on it.\",\"properties\":{\"contextId\":{\"description\":\"The VTA context the item is scoped to; the isolation boundary.\",\"minLength\":1,\"type\":\"string\"},\"createdAt\":{\"description\":\"When the item was first created at this key. MAY be absent on a tombstone whose body has been discarded, and on an item written before the maintainer kept versions.\",\"format\":\"date-time\",\"type\":\"string\"},\"deleted\":{\"description\":\"True when this is a tombstone: the item was deleted, and this entry exists so that a consumer syncing incrementally learns of the deletion. Tombstones are reaped after the maintainer's retention window; see `vta/memory/list`.\",\"type\":\"boolean\"},\"deletedAt\":{\"description\":\"When the item was deleted. Present only when `deleted` is true; equal to `updatedAt` for a tombstone the maintainer has not since rewritten.\",\"format\":\"date-time\",\"type\":\"string\"},\"key\":{\"$ref\":\"#/$defs/MemoryKey\"},\"updatedAt\":{\"description\":\"When the write that produced this `version` was applied. For a tombstone, when the delete was applied.\",\"format\":\"date-time\",\"type\":\"string\"},\"value\":{\"$ref\":\"#/$defs/MemoryValue\",\"description\":\"The remembered text. Absent when this is a tombstone or a metadata-only view.\"},\"valueBytes\":{\"description\":\"Size of the stored value in bytes over its UTF-8 encoding, as the maintainer measures it for the per-item cap. Present in metadata-only views so a consumer can decide what to fetch without fetching it; absent on a tombstone.\",\"minimum\":0,\"type\":\"integer\"},\"version\":{\"$ref\":\"#/$defs/MemoryVersion\",\"description\":\"The context counter value this item's most recent write took. Supply it as `expectedVersion` on the next write to make that write conditional on nothing having changed in between.\"}},\"required\":[\"contextId\",\"key\",\"version\",\"deleted\",\"updatedAt\"],\"title\":\"MemoryRecord\",\"type\":\"object\"},\"MemoryValue\":{\"description\":\"The remembered text: a fact, a summary, a preference. Opaque to the maintainer, which stores it as given and never interprets, rewrites or summarises it. The maintainer enforces a documented per-item cap on its size (see `vta/memory/put`).\",\"title\":\"MemoryValue\",\"type\":\"string\"},\"MemoryVersion\":{\"description\":\"A value of the context's monotonic write counter (see this schema's description). Server-assigned; a producer never chooses one.\",\"minimum\":1,\"title\":\"MemoryVersion\",\"type\":\"integer\"},\"Response\":{\"$anchor\":\"response\",\"additionalProperties\":false,\"description\":\"Success response to vta/memory/list. Type https://trusttasks.org/spec/vta/memory/list/0.2#response.\",\"properties\":{\"ext\":{\"$ref\":\"#/$defs/Ext\",\"description\":\"Ecosystem-defined extension members per SPEC.md §4.5.1.\"},\"highWatermark\":{\"description\":\"The context's current counter value; 0 for a context that has never been written. This is what a consumer stores as its next `sinceVersion` — NOT the maximum version among `items`, which is wrong whenever a `prefix` filtered a later change out, and undefined when the page is empty. A paginating consumer MUST NOT advance its stored watermark until it has drained the final page — the one with no `nextCursor` — because the pages of one feed share this value and adopting it early would skip the items still to come.\",\"minimum\":0,\"type\":\"integer\"},\"items\":{\"description\":\"Matching items in ascending key order in snapshot mode, and ascending version order in change-feed mode — the latter so that a consumer applying them in order reaches the same state as the maintainer. May be empty.\",\"items\":{\"$ref\":\"#/$defs/MemoryRecord\"},\"type\":\"array\"},\"nextCursor\":{\"description\":\"Opaque continuation token for the next page, sent back as the request's `cursor`. Present when more matching items exist beyond this page; absent on the last page.\",\"type\":\"string\"},\"tombstoneRetentionSeconds\":{\"description\":\"How long this maintainer retains tombstones before reaping them. Advisory, so a consumer can schedule its syncs to stay inside the window rather than discovering it has fallen out of it via vta/memory/list:watermarkTooOld.\",\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"items\",\"highWatermark\"],\"title\":\"VTA Memory List — response payload\",\"type\":\"object\"}},\"$id\":\"https://trusttasks.org/spec/vta/memory/list/0.2\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Enumerate the memory items in a context. Two modes, distinguished by whether `sinceVersion` is supplied. Without it this is a SNAPSHOT of live items, optionally narrowed by `prefix`. With it this is a CHANGE FEED: every item in the context whose version exceeds the watermark, tombstones included, which is what lets an agent's local cache on another device converge. Pagination is opaque-cursor based.\",\"properties\":{\"contextId\":{\"description\":\"The VTA context to enumerate; the isolation boundary.\",\"minLength\":1,\"type\":\"string\"},\"cursor\":{\"description\":\"An opaque continuation token from a previous response's `nextCursor`; a responder MUST NOT accept a cursor it did not issue. Consumers MUST treat it as opaque: never construct, decode, mutate, or infer meaning from one.\",\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\",\"description\":\"Ecosystem-defined extension members per SPEC.md §4.5.1.\"},\"includeDeleted\":{\"description\":\"Snapshot mode only: when true, tombstones still inside the retention window are returned alongside live items. Defaults to false. In change-feed mode tombstones are always returned and this member MUST NOT be set to false — a change feed that omits deletions cannot converge.\",\"type\":\"boolean\"},\"includeValues\":{\"description\":\"When true, each returned item carries its `value`. Defaults to TRUE — unlike vta/app-state/list — because recalling the text is what an agent lists memory for, and 0.1 always returned values. Set it false for the metadata view (key, version, timestamps, `valueBytes`), which makes a scan of a large context cheap.\",\"type\":\"boolean\"},\"limit\":{\"description\":\"The most items to return; the responder chooses a default and MAY return fewer, which is likely when `includeValues` is in effect and the values are large.\",\"maximum\":1000,\"minimum\":1,\"type\":\"integer\"},\"prefix\":{\"description\":\"Restrict to items whose `key` begins with this byte prefix, compared over the UTF-8 encoding. Lets an agent recall one family of items — `contact/`, `preference/` — without dragging the whole context through the response.\",\"maxLength\":512,\"minLength\":1,\"type\":\"string\"},\"sinceVersion\":{\"description\":\"Watermark. Selects change-feed mode: only items whose `version` is strictly greater are returned, tombstones included. Supply the `highWatermark` from the previous sync, or 0 for a first full pull in change-feed form.\",\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"contextId\"],\"title\":\"VTA Memory List — payload\",\"type\":\"object\"}\n",
    );
